# Nó Code do N8N
# Modo: "Run Once for All Items"

# Percentuais de distribuição por perfil e produto
DISTRIBUICAO = {
    "Conservador": {
        "Poupança": 0.10,
        "CDB Liquidez Diária": 0.50,
        "Tesouro Selic": 0.40,
    },
    "Moderado": {
        "CDB Prefixado": 0.30,
        "Fundo Multimercado": 0.30,
        "Tesouro IPCA+": 0.40,
    },
    "Arrojado": {
        "Ações ETF": 0.30,
        "Fundo de Ações": 0.30,
        "Criptomoedas": 0.40,
    },
}


def parse_saldo(valor: str) -> float:
    """Converte 'R$ 12.500,00' -> 12500.00"""
    if isinstance(valor, (int, float)):
        return float(valor)
    limpo = "".join(c for c in str(valor) if c.isdigit() or c in ",.-")
    # Formato brasileiro: ponto como milhar, vírgula como decimal
    if "," in limpo:
        limpo = limpo.replace(".", "").replace(",", ".")
    return float(limpo)


def formatar_brl(valor: float) -> str:
    """Formata 12500.0 -> 'R$ 12.500,00'"""
    return f"R$ {valor:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")


# Coleta todos os itens recebidos
resultados = []

for item in _items:
    dados = item.get("json", {})

    clientes = dados.get("body", {}).get("clientes") or dados.get("clientes", [])
    investimentos = dados.get("investimentos") or dados.get("body", {}).get("investimentos", [])

    # Indexa investimentos por perfil para busca rápida
    investimentos_por_perfil = {}
    for inv in investimentos:
        investimentos_por_perfil.setdefault(inv["perfil"], []).append(inv)

    sugestoes = []

    for cliente in clientes:
        nome = cliente["nome"]
        email = cliente["email"]
        perfil = cliente["perfil"]
        saldo = parse_saldo(cliente["saldo"])

        regras = DISTRIBUICAO.get(perfil, {})
        produtos_disponiveis = {
            inv["produto"]: inv for inv in investimentos_por_perfil.get(perfil, [])
        }

        for produto, percentual in regras.items():
            info = produtos_disponiveis.get(produto)
            if not info:
                continue

            valor_aplicado = round(saldo * percentual, 2)

            # Só sugere se atingir o mínimo do produto
            if valor_aplicado < info["minimo"]:
                continue

            sugestoes.append({
                "cliente": nome + ";" + email,
                "investimento": produto,
                "valor aplicado": formatar_brl(valor_aplicado),
            })

    # Mantém os dados originais e adiciona a chave "sugestao"
    novo_item = dict(dados)
    novo_item["sugestao"] = sugestoes
    resultados.append({"json": novo_item})

return resultados
